using CarRacer.Game.Discovery;
using CarRacer.Game.DriveTest;
using CarRacer.Game.Net;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace CarRacer.Game
{
    /// <summary>
    /// Builds each screen from code so the Bootstrap scene can stay empty (and be generated by the
    /// build script). For now the screens are the LAN discovery test and the drive test (alone or
    /// in a hosted or joined session); each lives under one root object, which is destroyed when
    /// switching to another screen.
    /// </summary>
    public static class Bootstrap
    {
        public const string SceneName = "Bootstrap";

        private static GameObject _screen;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void OnFirstSceneLoaded()
        {
            if (SceneManager.GetActiveScene().name != SceneName)
            {
                return;
            }

            Application.targetFrameRate = 60;
            Screen.sleepTimeout = SleepTimeout.NeverSleep;

            // Fixed 50 Hz physics on every device (design doc §4).
            Time.fixedDeltaTime = 0.02f;
            ShowDiscoveryScreen();
        }

        public static void ShowDiscoveryScreen()
        {
            var root = new GameObject(nameof(DiscoveryTestScreen));
            var camera = new GameObject("Main Camera").AddComponent<Camera>();
            camera.transform.SetParent(root.transform, false);
            camera.tag = "MainCamera";
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.12f, 0.14f, 0.2f);
            root.AddComponent<DiscoveryTestScreen>();
            Show(root);
        }

        public static void ShowDriveTest()
        {
            Show(DriveTestArena.Create().gameObject);
        }

        /// <summary>Hosts a session and opens the free drive for everyone who joins.</summary>
        public static void HostGame(string playerName)
        {
            Show(DriveTestArena.Create(startSession: () => NetworkSession.StartHosting(playerName)).gameObject);
        }

        public static void JoinGame(string playerName, string address, ushort port)
        {
            Show(DriveTestArena.Create(startSession: () => NetworkSession.Join(playerName, address, port)).gameObject);
        }

        private static void Show(GameObject screen)
        {
            if (_screen != null)
            {
                Object.Destroy(_screen);
            }

            _screen = screen;
        }
    }
}
